pub struct Passage { pub from: String, pub to: String, pub minutes: u64 }

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Tour { pub rooms: Vec<String>, pub minutes: u64 }

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TourError { EmptyRoom, SelfPassage, DuplicatePassage, CostOverflow }

pub fn analyze_tours(passages: &[Passage]) -> Result<Vec<Tour>, TourError> {
    let mut names = BTreeSet::new();
    let mut pairs = HashSet::new();
    let mut costs = HashMap::new();
    for passage in passages {
        if passage.from.is_empty() || passage.to.is_empty() { return Err(TourError::EmptyRoom); }
        if passage.from == passage.to { return Err(TourError::SelfPassage); }
        let pair = if passage.from < passage.to {
            (passage.from.clone(), passage.to.clone())
        } else {
            (passage.to.clone(), passage.from.clone())
        };
        if !pairs.insert(pair.clone()) { return Err(TourError::DuplicatePassage); }
        names.insert(passage.from.clone());
        names.insert(passage.to.clone());
        costs.insert(pair, passage.minutes);
    }
    let names: Vec<String> = names.into_iter().collect();
    if names.is_empty() { return Ok(Vec::new()); }
    let mut answer = Vec::new();
    fn build(names: &[String], costs: &HashMap<(String, String), u64>, used: &mut [bool], path: &mut Vec<String>, total: u64, out: &mut Vec<Tour>) -> Result<(), TourError> {
        if path.len() == names.len() {
            out.push(Tour { rooms: path.clone(), minutes: total });
            return Ok(());
        }
        for i in 0..names.len() {
            if used[i] { continue; }
            let next_total = if let Some(previous) = path.last() {
                let pair = if previous < &names[i] { (previous.clone(), names[i].clone()) } else { (names[i].clone(), previous.clone()) };
                let Some(edge) = costs.get(&pair) else { continue; };
                total.checked_add(*edge).ok_or(TourError::CostOverflow)?
            } else { total };
            used[i] = true;
            path.push(names[i].clone());
            build(names, costs, used, path, next_total, out)?;
            path.pop();
            used[i] = false;
        }
        Ok(())
    }
    build(&names, &costs, &mut vec![false; names.len()], &mut Vec::new(), 0, &mut answer)?;
    answer.sort_by(|a, b| a.minutes.cmp(&b.minutes));
    Ok(answer)
