#[path = "solution.rs"]
mod solution;

use solution::{analyze_tours, Passage, Tour, TourError};

fn passage(from: &str, to: &str, minutes: u64) -> Passage {
    Passage { from: from.to_string(), to: to.to_string(), minutes }
}

#[test]
fn public_types_have_required_traits() {
    fn require_traits<T: Clone + std::fmt::Debug + Eq>() {}
    require_traits::<Passage>();
    require_traits::<Tour>();
    require_traits::<TourError>();
}

#[test]
fn no_passages_produce_no_known_rooms_or_tours() {
    assert_eq!(analyze_tours(&[]), Ok(Vec::new()));
}

#[test]
fn path_graph_produces_both_orientations_in_lexicographic_order() {
    let passages = vec![passage("B", "C", 3), passage("A", "B", 2)];
    let before = passages.clone();
    let tours = analyze_tours(&passages).unwrap();

    assert_eq!(tours, vec![
        Tour { rooms: vec!["A".to_string(), "B".to_string(), "C".to_string()], minutes: 5 },
        Tour { rooms: vec!["C".to_string(), "B".to_string(), "A".to_string()], minutes: 5 },
    ]);
    assert_eq!(passages, before);
}

#[test]
fn complete_three_room_graph_returns_every_oriented_tour_sorted() {
    let passages = vec![passage("A", "B", 1), passage("B", "C", 2), passage("A", "C", 4)];
    let tours = analyze_tours(&passages).unwrap();
    let expected_rooms = vec![
        vec!["A", "B", "C"],
        vec!["A", "C", "B"],
        vec!["B", "A", "C"],
        vec!["B", "C", "A"],
        vec!["C", "A", "B"],
        vec!["C", "B", "A"],
    ];
    assert_eq!(tours.iter().map(|t| t.rooms.iter().map(String::as_str).collect::<Vec<_>>()).collect::<Vec<_>>(), expected_rooms);
    assert_eq!(tours.iter().map(|t| t.minutes).collect::<Vec<_>>(), vec![3, 6, 5, 6, 5, 3]);
}

#[test]
fn disconnected_graph_has_no_complete_tour() {
    let passages = vec![passage("A", "B", 1), passage("C", "D", 1)];
    assert_eq!(analyze_tours(&passages), Ok(Vec::new()));
}

#[test]
fn names_are_exact_and_case_sensitive() {
    let tours = analyze_tours(&[passage("A", "a", 7)]).unwrap();
    assert_eq!(tours, vec![
        Tour { rooms: vec!["A".to_string(), "a".to_string()], minutes: 7 },
        Tour { rooms: vec!["a".to_string(), "A".to_string()], minutes: 7 },
    ]);
}

#[test]
fn validation_rejects_empty_self_and_unordered_duplicates() {
    assert_eq!(analyze_tours(&[passage("", "A", 1)]), Err(TourError::EmptyRoom));
    assert_eq!(analyze_tours(&[passage("A", "", 1)]), Err(TourError::EmptyRoom));
    assert_eq!(analyze_tours(&[passage("same", "same", 1)]), Err(TourError::SelfPassage));
    assert_eq!(
        analyze_tours(&[passage("A", "B", 1), passage("B", "A", 9)]),
        Err(TourError::DuplicatePassage)
    );
}

#[test]
fn validation_errors_follow_input_order() {
    let duplicate_before_empty = vec![
        passage("A", "B", 1),
        passage("B", "A", 2),
        passage("", "C", 3),
    ];
    assert_eq!(analyze_tours(&duplicate_before_empty), Err(TourError::DuplicatePassage));

    let self_before_duplicate = vec![
        passage("X", "X", 1),
        passage("A", "B", 1),
        passage("B", "A", 2),
    ];
    assert_eq!(analyze_tours(&self_before_duplicate), Err(TourError::SelfPassage));
}

#[test]
fn overflowing_cost_of_an_otherwise_valid_tour_is_an_error() {
    let passages = vec![passage("A", "B", u64::MAX), passage("B", "C", 1)];
    assert_eq!(analyze_tours(&passages), Err(TourError::CostOverflow));
}

